-- Breeder class + Advanced Class (Botanist, Chef, Evolver, Medic, Move Tutor) Features, extracted from
-- the Player's Handbook PDF pages 30-43. Part of [[Add all Class features to the list]]. Matches the
-- same shape/conventions as the existing Ace trainer/Researcher rows in 20260725120300_seed_features.sql
-- (Title Case names, sentence-case descriptions, "Stat Increase and Advanced Class" kept as one combined
-- row per the corrective fix applied to Ace trainer in 20260810100000). Where a Feature teaches a move,
-- the description names the move(s) only (mechanics live in the existing `moves` catalog), matching the
-- established simplification pattern -- not every named move exists in that catalog yet (confirmed via
-- grep for the Move Tutor subclass's move lists), which is a separate, out-of-scope data gap for a future
-- FR, not blocking this one since Feature descriptions are free text, not FK-constrained to `moves`.
insert into features (name, description, class_id, subclass_id, level_required) values
  ('Hatcher', 'Your loving care of the eggs you receive brings out your new Pokémon with particular haste. Your eggs in your care never take longer than 72 hours to hatch', (select id from classes where name = 'Breeder'), null, 1),
  ('Natural Edge', 'Your Pokémon are born with a natural lead on other trainer’s Pokémon, your caring watch has given them a reason to be more, for you. Whenever you hatch an egg, after you know the Pokémon’s nature, choose one of Attack, Defense, Special Attack, Special Defense, and Speed. That Pokémon’s chosen stat is permanently raised X, where X is half of either your Defense or Special Defense modifier', (select id from classes where name = 'Breeder'), null, 1),
  ('Philoprogenitive', 'You put your Pokémon children before yourself. Whenever one of your hatched Pokémon is targeted with an attack and hit, if they are within 10ft of you, you may move to your Pokémon and take the damage and effects they would have taken for them as a free action. You may use this feature as many times as you would like within the same round, regardless of turn order and regardless of whether or not you have already acted', (select id from classes where name = 'Breeder'), null, 2),
  ('Stat Increase and Advanced Class', 'Choose two different Trainer Stats to increase by 1, then gain 1d4 max HP. You only gain new stats at levels 3, 7, and 11. Choose a Breeder Advanced Class or a different base Class. You can only ever gain a single Class or Advanced Class at a time, at level 3, level 7, and level 11', (select id from classes where name = 'Breeder'), null, 3),
  ('Egg Finder', 'Something about your care raises the likelihood of two matched Pokémon producing a Pokémon egg for you. Whenever you make an Breeding Check for any two Pokémon, you may make three checks and use the best result', (select id from classes where name = 'Breeder'), null, 4),
  ('Unexpected Hatch', 'Your eggs begin to hatch across species!? Whenever you hatch an egg that you found after making an Breeding Check, you may flip a coin. If you win the flip, you may choose to have the egg hatch as a Pokémon of the father’s species instead of the default mother’s species', (select id from classes where name = 'Breeder'), null, 5),
  ('Natural Breeder', 'You’ve learned just how to influence your baby Pokémon’s first moments of life. When you hatch an egg, you may choose which of Attack, Defense, Special Attack, Special Defense, or Speed is positively or negatively influenced by nature. The nature is still randomized, but will be a nature that matches your preference when using Natural Breeder. In addition, if you don’t choose to influence the Pokémon’s nature you can pick its gender', (select id from classes where name = 'Breeder'), null, 6),
  ('Stat Increase and Advanced Class', 'Choose two different Trainer Stats to increase by 1, then gain 1d4 max HP. You only gain new stats at levels 3, 7, and 11. Choose a Breeder Advanced Class or a different base Class. You can only ever gain a single Class or Advanced Class at a time, at level 3, level 7, and level 11', (select id from classes where name = 'Breeder'), null, 7),
  ('Parental Hyperlexia', 'You begin to pick on the slightest hints, differences in tone, and micro expressions from your Pokémon as if they are speaking to you in a human language. You can understand any Pokémon that you hatched with a loyalty of 3 or higher, when it tries to speak to you in its own Pokémon languages. If the Pokémon’s unable to speak to you in a comprehensible sense, you still understand it’s general needs and you still understand anything it might be trying to communicate to you', (select id from classes where name = 'Breeder'), null, 8),
  ('Inherited Moves', 'Your pairings yield powerful children often with powers beyond the baby Pokémon''s ability to understand; with your guidance they will wield awesome attacks. Whenever you hatch your eggs, choose any one move from either parent and give it to your baby Pokémon', (select id from classes where name = 'Breeder'), null, 9),
  ('Scrambled Moves', 'Your influence on your Pokémon while they are eggs continues to yield unique results. Whenever you hatch an egg, choose one of the three moves the Pokémon is assigned in the Pokédex. They are given an appropriate different move by your GM that are aligned with its proficiencies (different type, same frequency)', (select id from classes where name = 'Breeder'), null, 10),
  ('Stat Increase and Advanced Class', 'Choose two different Trainer Stats to increase by 1, then gain 1d4 max HP. You only gain new stats at levels 3, 7, and 11. Choose a Breeder Advanced Class or a different base Class. You can only ever gain a single Class or Advanced Class at a time, at level 3, level 7, and level 11', (select id from classes where name = 'Breeder'), null, 11),
  ('Unlikely Pairings', 'The mysterious ways that Pokémon create eggs are still unclear to you, but you’ve figured out a way to coerce eggs from Pokémon that otherwise would never make an egg. When trying to have Pokémon make Pokémon eggs in privacy, they do not need to have a matching egg group', (select id from classes where name = 'Breeder'), null, 12),
  ('Familial Bond', 'Your Pokémon treat you as if you were their actual parent. Any Pokémon you’ve hatched starts at loyalty 3 with you. It takes intentional and malicious mistreatment to lower these Pokémon’s loyalties. In addition, any Pokémon you obtain are quick to warm up to you and not treat you as a hostile, in no more than one week any Pokémon you obtain reach loyalty 3', (select id from classes where name = 'Breeder'), null, 13),
  ('Gleaming Eggs', 'Your warm influence brings out a rare quality on occasion from your baby Pokémon. Whenever you hatch one of your eggs, roll 1d20 and add your Defense or Special Defense modifier. On 20 or higher, the Pokémon that hatches is shiny', (select id from classes where name = 'Breeder'), null, 14),
  ('Matchmaker', 'You’ve become a master Breeder and can guarantee the Pokémon eggs that you desire. Once per day, when you make an Breeding Check for two Pokémon, of which at least one of the two is your Pokémon, you are guaranteed to find an egg. When the egg hatches, you pick which species of the two parents the Pokémon is, which sex the Pokémon has, and which nature the Pokémon has', (select id from classes where name = 'Breeder'), null, 15),

  ('Berry Mixer', 'When it comes to berry treats, you’re an expert. Whenever you’re making any kind of food or item that requires berries, you are considered a certified expert and can supply your wares to specialty stores (usually at half their value), or to strangers willing to pay for your expertise', (select class_id from subclasses where name = 'Botanist'), (select id from subclasses where name = 'Botanist'), 1),
  ('Botanical Encyclopedia', 'You’ve memorized every book there is on botany in the Pokémon world. You can instantly identify any berries, plants, or fungi and know any of their special properties. You also can tell if any of them have been modified to have unique attributes. In addition, you can identify any Grass-type Pokémon on sight, or any Pokémon known to work with, or that pretends to be, flora', (select class_id from subclasses where name = 'Botanist'), (select id from subclasses where name = 'Botanist'), 1),
  ('Berry Finder', 'You apply your encyclopedic knowledge to the field and know where to best find berries. Whenever you make any skill checks related to berries, or finding them, you may roll twice and use the better result', (select class_id from subclasses where name = 'Botanist'), (select id from subclasses where name = 'Botanist'), 2),
  ('Berry Booster', 'Your care for your plants is evident by the particular energy they release when consumed. Whenever a Pokémon consumes berries that you’ve grown, double any numerical effect the berry might have', (select class_id from subclasses where name = 'Botanist'), (select id from subclasses where name = 'Botanist'), 3),
  ('Growth Spurt', 'You’ve started to apply a special fertilizer to your plants, promising quick results. Whenever you plant berries, including in a portable planter, it will never take more than 48 hours for the plant to produce fruit. In addition, if you roll under 6 while making Nature checks while caring for Berry plants, treat the roll as a 6', (select class_id from subclasses where name = 'Botanist'), (select id from subclasses where name = 'Botanist'), 4),
  ('Berry Combination', 'You begin to practice with the qualities of berries by extracting and injecting different berries together. Once per day, after spending an hour with two of your berries, you destroy one and give its flavor and effects to the other berry to create one berry with the effects of both. Call the combination whatever you’d like. You may not combine a berry with an already combined berry', (select class_id from subclasses where name = 'Botanist'), (select id from subclasses where name = 'Botanist'), 6),
  ('Apricorn Finder', 'You apply your knowledge of berries to lesser known and lesser studied apricorn, whenever you make any skill checks related to apricorns, or finding them, you may roll twice and use the better result', (select class_id from subclasses where name = 'Botanist'), (select id from subclasses where name = 'Botanist'), 7),
  ('Hybridization', 'You begin to apply your studies to a berry plant itself. Whenever you plant a berry, you can plant two berries together to produce a tree that grows berries with the flavors and effects of both of the planted berries. This includes berries you may plant in a portable planter. Call the resulting combination whatever you’d like. You may not hybridize a berry with an already hybridized or combined berry', (select class_id from subclasses where name = 'Botanist'), (select id from subclasses where name = 'Botanist'), 8),
  ('Berry Seeker', 'You find unusual signs of rarer berries and explore the space around you to find unusual and lesser seen berries. Whenever you make any skill checks related finding berries, you may attempt to find an uncommon berry. If you do, only roll once on your skill check. If you succeed, you find one of the follow berries of your choice: Pomeg Berry, Kelpsy Berry, Qualot Berry, Hondew Berry, Grepa Berry, Tamato Berry, Occa Berry, Passho Berry, Wacan Berry, Rindo Berry, Yache Berry, Chople Berry, Kebia Berry, Shuca Berry, Coba Berry, Payapa Berry, Tanga Berry, Charti Berry, Kasib Berry, Haban Berry, Colbur Berry, Babiri Berry, Chilan Berry, or Roseli Berry', (select class_id from subclasses where name = 'Botanist'), (select id from subclasses where name = 'Botanist'), 10),
  ('Miniature Specimen', 'You apply a theory towards creating smaller, but still just as effective berry plants. You can grow two plants in a portable planter at the same time, and the berries these plants produce are small enough to fit in the palm of your hand. Berries produced with the miniature specimen feature cannot be stolen from any Pokémon who is holding onto one during battle', (select class_id from subclasses where name = 'Botanist'), (select id from subclasses where name = 'Botanist'), 11),
  ('Rare Berry Seeker', 'You may apply your vast knowledge base to explore wild space and locate treasures in the berry collecting world. Whenever you make any skill checks related finding berries, you may attempt to find a rare berry. If you do, only roll once on your skill check. If you succeed, you find one of the follow berries of your choice: Liechi Berry, Ganlon Berry, Salac Berry, Petaya Berry, Apicot Berry, Lansat Berry, Starf Berry, Enigma Berry, Micle Berry, Custap Berry, Joboca Berry, Rowap Berry, Kee Berry, or Maranga Berry', (select class_id from subclasses where name = 'Botanist'), (select id from subclasses where name = 'Botanist'), 12),
  ('Berry Monstrosities', 'You’ve mastered the hybridizations and combination of natural berries and put it to unbelievable use and execution. When using your Berry Combination or Hybridization features, the berries you make can have a total of five different qualities from different berries. This will combine all flavors and all effects. If you combine or hybridize a sixth berries into your monstrosities, chose another berry’s flavor and effects to replace in said monstrosity. Call the combination whatever you’d like', (select class_id from subclasses where name = 'Botanist'), (select id from subclasses where name = 'Botanist'), 13),

  ('Energy Shot', 'You’ve concocted a drink that really gives you an adrenaline rush, it could be useful out there in the wilds. Once per day, after one hour of work in on it, you create one pint of an energy drink for trainers. Call it whatever you’d like. You have enough for four servings of the drink. When one serving is consumed, it gives a trainer temporary hit points equal the sum of your Defense and Special Defense stat. The drink’s effect wears off after an hour. Drinking multiple servings will remove any temporary hit points gained by the drink. The drink’s potency wears off after 24 hours and then becomes a regular drink', (select class_id from subclasses where name = 'Chef'), (select id from subclasses where name = 'Chef'), 1),
  ('Soul Food', 'You’re a great chef and have loads of experience whipping up meals. When looking for edible food in the wild, you can add your Defense or Special defense modifiers while making skill checks. It takes you less than 20 mins to create a soulful meal out of any edible ingredients for ten people and/or Pokémon. Whenever a Pokémon consumes a soulful meal within an hour of its creation, they are relaxed unless they are agitated again (it takes at least 5 mins to consume a meal). Your Pokémon quickly gain loyalty to you if you’re feeding them often and are very unlikely to lose loyalty unless there’s any intentional mistreatment', (select class_id from subclasses where name = 'Chef'), (select id from subclasses where name = 'Chef'), 1),
  ('Wild Bait', 'You can create powerful aromas that attract various wilds to a place of your choosing. After 30 mins of work, you create a dish of wild bait. The bait has a powerful smell that will lure wild Pokémon to its location once you ready it. If you and your party are not sufficiently hidden, wilds may approach but then flee if any wilds detect you or your party', (select class_id from subclasses where name = 'Chef'), (select id from subclasses where name = 'Chef'), 2),
  ('Sugar Rush', 'You can produce treats that energize your Pokémon like nothing else. Once per day, after thirty minutes of work in on it, you create one serving of a sugary energy drink for Pokémon. Call it whatever you’d like. When it is consumed, it gives a Pokémon temporary hit points equal the sum of your Defense and Special Defense stat. The drink’s effect wears off after an hour. Drinking multiple servings will remove any temporary hit points gained by the drink. The drink’s potency wears off after 72 hours and then becomes a regular drink', (select class_id from subclasses where name = 'Chef'), (select id from subclasses where name = 'Chef'), 3),
  ('Pâtissier', 'You begin practicing the art of dessert and can spend time to create delicious replicas of famous treats. Once per day, after 30 mins of work you can create two of any of the following treats. Unlike real versions of these treats, your food made with the Pâtissier feature do not have their effects after 48 hours, instead only tasting delicious. Big Malasada, Casteliacone, Lava Cookie, Rage Candy Bar, or Sweet Heart recover 10 Hit Points (Pokémon). Berry Juice, Lumiose Galette, Old Gateau, Pewter Crunchies, or Shalour Sable remove any affliction', (select class_id from subclasses where name = 'Chef'), (select id from subclasses where name = 'Chef'), 4),
  ('Herbal Medicine', 'You improve several qualities of the treats you can make, but less people would call them treats now. Once per day, after 10 mins of work you can create one of the following medicines. Your Pokémon are not repulsed by your Herbal Medicine, but another trainer’s Pokémon or wild Pokémon will be disgusted. Heal Powder removes any affliction. Energy Powder recovers 25 Hit Points (Pokémon)', (select class_id from subclasses where name = 'Chef'), (select id from subclasses where name = 'Chef'), 6),
  ('Vile Cook', 'You figure out how to creates food that hide undesirable effects underneath delicious disguises. Whenever you make food, or an edible item, you may make the food Poison the consumer, Paralyze the consumer or put the consumer to Sleep. The tampered food loses its potency after one hour and becomes regular edible food', (select class_id from subclasses where name = 'Chef'), (select id from subclasses where name = 'Chef'), 7),
  ('Palette Pleaser', 'You’ve mastered flavor in every form. Whenever you make a meal, or mix any ingredients to make a food item with any effects, you make it in a way that is pleasing to anyone or any Pokémon who consumes it regardless of their nature, preferred flavors, or disliked flavors', (select class_id from subclasses where name = 'Chef'), (select id from subclasses where name = 'Chef'), 8),
  ('Power Recovery', 'Your soul food becomes invigorating and empowers your Pokémon to unleash powerful attacks as if they’ve rested for hours. Pokémon who have eaten your soulful food may again use their 3/day or 1/day moves as if they have rested for 8 hours. Pokémon may not benefit from the Power Recovery feature multiple times per day', (select class_id from subclasses where name = 'Chef'), (select id from subclasses where name = 'Chef'), 10),
  ('Powerful Herbs', 'You’ve strengthened your foul-smelling recipes. Once per day, after one hour of work you can create one of the following medicines. Your Pokémon are not repulsed by your Powerful Herbs, but another trainer’s Pokémon or wild Pokémon will be disgusted. Energy Root recovers 50 Hit Points (Pokémon). Revival Herb recovers an unconscious Pokémon to half of their max HP', (select class_id from subclasses where name = 'Chef'), (select id from subclasses where name = 'Chef'), 11),
  ('Leftovers', 'Through your practice, you discovered a way to create a meal that continues to heal a Pokémon after it’s consumed. Once per day, after working for one hour you create a serving of Leftovers. As an action, start consuming Leftovers for 1 min (10 rounds) or until at max HP. While consuming Leftovers, regain 10 hp per round. Afterwards, Leftovers is destroyed', (select class_id from subclasses where name = 'Chef'), (select id from subclasses where name = 'Chef'), 12),
  ('Master Chef', 'You’ve proven yourself to be an unmatched chef. Nothing can dislike your food, and you know how to make any meal by tasting or looking at it once. Any effects from any food you’ve made are doubled when possible. This includes things you make with or without your features. In addition, Vile Cook can be used to Toxify food and Revival Herbs that you’ve made will recover an unconscious Pokémon to full HP', (select class_id from subclasses where name = 'Chef'), (select id from subclasses where name = 'Chef'), 13),

  ('Early Evolution', 'Every Pokémon has different triggers that encourage evolution and you’ve learned to nurture these different influences and induce evolution. Your Pokémon are unhindered by any natural timing to evolve and can evolve regardless of day or night time constraints. Your Pokémon whose evolutions that require environmental influences may evolve anywhere. Pokémon who need to evolve based solely on loyalty or their relationship with you evolve much faster, even if they are barely a week old. In addition, in rare occasions, your Pokémon may evolve twice rapidly into its final evolution if given the opportunity', (select class_id from subclasses where name = 'Evolver'), (select id from subclasses where name = 'Evolver'), 1),
  ('Mega Stone Smith', 'After studying mega stones, you’ve figured out how to imbue simple marbles with the mysterious spirit that enables Pokémon to mega evolve. Once per week, after five hours of work, you create a Keystone exclusively for your use or you create a Mega Stone exclusively for one of your fully-evolved Pokémon. When creating a Mega Stone, decide which stats are boosted while the Pokémon is using the created Mega Stone. You can modify Attack, Defense, Special Attack, Special Defense, or Speed by a total of 4 points, but no individual stat can be modified by more than 2. You may not affect any stats negatively. You choose how your Pokémon’s physical appearance changes appropriately. Special: Mega Evolution is done once per day by activating your Keystone with one of your Pokémon who has a Mega Stone. It lasts for 10 minutes', (select class_id from subclasses where name = 'Evolver'), (select id from subclasses where name = 'Evolver'), 1),
  ('Elemental Evolution', 'Working with some theories about the effects of elemental stones on Pokémon, you’ve figured out how to induce elemental evolution. Once per day, you may spend one hour with a Pokémon who can evolve with the use of any evolution stone and they will evolve at the end of that hour. In addition, you’ve figured out how to repress evolution in a Pokémon and after spending one hour with one of your Pokémon, you can abate evolution for 48 hours without the use of an Everstone', (select class_id from subclasses where name = 'Evolver'), (select id from subclasses where name = 'Evolver'), 2),
  ('Evolution Guidance', 'Your training and care helps to mold your Pokémon’s futures and helps their paths of evolution. If your Pokémon has a branched evolution, when it evolves you may choose what it evolves into regardless of any other factors in its evolution. The Evolution Guidance feature overrides requirements during evolutions such as gendered evolutions (Gallade, Vespiquen), evolutions that differ based on time of day (Cascoon, Lycanroc), environment influenced evolutions (Wormadam S, Weezing A), stone evolutions (Bellossom, Vaporeon), or stat based evolutions (Hitmonchan, Gorebyss). This means you could have a male Nidorina, a night time Silcoon, a Fairy type Rapidash from a Fire type Ponyta, a Glaceon from a Moon Stone, or any other unusual evolution', (select class_id from subclasses where name = 'Evolver'), (select id from subclasses where name = 'Evolver'), 3),
  ('Keystone Burst', 'Keystones usually need time to regain their ambient energy after use, however you’ve trained your Pokémon to only dip into the Key Stone’s power with their Mega Stones instead of draining it completely. Your Keystone may be used twice per day or three times per day if you only Mega Evolve the same Pokémon each time. You may still only have one Mega Pokémon at a time', (select class_id from subclasses where name = 'Evolver'), (select id from subclasses where name = 'Evolver'), 4),
  ('Mega Stone Shift', 'Spending some time with your Mega Stones can give you some insight to their magical properties; with a little bit of focus you can change how your Mega Stones change your Pokémon. After two hours of work, one of your unique Mega Stones will alter your Pokémon’s types by replacing one type or by adding one type while the Pokémon is Mega Evolved. You choose how your Pokémon’s physical appearance changes appropriately', (select class_id from subclasses where name = 'Evolver'), (select id from subclasses where name = 'Evolver'), 6),
  ('Key Stone Stretch', 'Keystones ring while your Pokémon are Mega Evolved, but you’ve learned to quell that into a hum, prolonging a Mega Evolution’s stay. Your Pokémon’s Mega Evolutions can retain their form for up to one hour, even if returned to their Poke Ball', (select class_id from subclasses where name = 'Evolver'), (select id from subclasses where name = 'Evolver'), 7),
  ('Peak Form', 'Raising your Pokémon through their evolutions and keeping them in top shape has increased their performance. When one of your Pokémon evolves into its final stage of evolution, choose two of Attack, Defense, Special Attack, Special Defense, or Speed and permanently add 1 to that Pokémon’s stats. Additionally, for any of your fully-evolved Pokémon that you’ve owned for at least one week who haven’t benefitted from Peak Form yet, choose two of Attack, Defense, Special Attack, Special Defense, or Speed and permanently add 1 to that Pokémon’s stats', (select class_id from subclasses where name = 'Evolver'), (select id from subclasses where name = 'Evolver'), 8),
  ('Keystone Overflow', 'Your Pokémon have grown to use the flow of energy from the Key Stone and can even borrow its energy from each other when standing together in battle! You may have two Mega Pokémon at the same time', (select class_id from subclasses where name = 'Evolver'), (select id from subclasses where name = 'Evolver'), 10),
  ('Potential Break', 'Mega Stones bring Pokémon to unreal levels of power, but to most you need to already be strong to use a Mega Stone with your Key Stone. However, you’ve figured out a way to induce Mega Evolution with unreal results. If you own a Mega Stone that corresponds to a Mega Evolution that appears in the Pokédex, your not-fully-evolved Pokémon that will eventually be fully compatible with a Mega Stone may already use the Mega Stone. For example, if you own Blazikenite or have created a Mega Stone to Mega Evolve Blaziken, your Torchic or Combusken could use it to turn into Mega Blaziken', (select class_id from subclasses where name = 'Evolver'), (select id from subclasses where name = 'Evolver'), 11),
  ('Evolution Shift', 'Pokémon have their previous selves, potential selves, and sometimes impossible selves within and you’ve developed a way to manipulate and work with your Pokémon to bring out any hidden part. Once per day, after working for five hours with one of your Pokémon you may return it to its previous stage of evolution or change its evolution to another in its branch of evolutions. You could for example change your Rapidash into a Rapidash (Forest Glade), your Purrserker into a Persian, or your Poliwrath into a Politoed. Evolution Shift removes any benefits given to your Pokémon by Peak Form if they are unevolved during Evolution Shift until that Pokémon evolves again', (select class_id from subclasses where name = 'Evolver'), (select id from subclasses where name = 'Evolver'), 12),
  ('Keystone Kaleidoscope', 'Evolution is different for every Pokémon and can continue to change and create new surprises for everyone. Whenever you Mega Evolve a Pokémon, you may choose which of its stats are modified by its Mega Stone and which types it becomes (you may choose different stats and types each time). You must still follow the Mega Stone rules of the features Mega Stone Smith and Mega Stone Shift while Mega Evolving your Pokémon', (select class_id from subclasses where name = 'Evolver'), (select id from subclasses where name = 'Evolver'), 13),

  ('Muscle Relaxants', 'While they may only help without cure sometimes, your careful application of injected relaxants is a sure fix for any paralyzed ally. 3/day you may use your medical field kit as an action to cure any adjacent trainer or Pokémon of Paralysis', (select class_id from subclasses where name = 'Medic'), (select id from subclasses where name = 'Medic'), 1),
  ('Treat Minor Wound', 'Your study of medicine has led to more effective use of your kit to heal the broken, damaged, and hurt. 3/day you may use your medical field kit as an action to heal any adjacent trainer or Pokémon 10 hit points, then give them 5 temporary hit points which last for 10 mins. In addition, you may not use your Medic features on unwilling, conscious targets. (A Pokémon who is healed this way cannot use a Move during the same round)', (select class_id from subclasses where name = 'Medic'), (select id from subclasses where name = 'Medic'), 1),
  ('Medicinal Expert', 'Your training and practice has led you to some improved procedures that help will your friends in a pinch. Whenever you use a restorative item such as an Antidote or Potion, or a Medic feature on an allied trainer or Pokémon, heal the target additional hit points equal to your Defense or Special Defense modifier', (select class_id from subclasses where name = 'Medic'), (select id from subclasses where name = 'Medic'), 2),
  ('Better Living Through Medicine', 'Careful study and repetition has given your hands the precision and skill to move rapidly and help those in need. During your turn, you may use two Medic features on adjacent targets during the same turn as one action. You still deplete your uses per day on any of your Medic features used', (select class_id from subclasses where name = 'Medic'), (select id from subclasses where name = 'Medic'), 3),
  ('Treat Wound', 'Your continuous practice of medicine has led to more effective use of your kit to heal the injured. 3/day you may use your medical field kit as an action to heal any adjacent trainer or Pokémon 20 hit points, then give them 10 temporary hit points which last for 10 mins. (A Pokémon who is healed this way cannot use a Move during the same round)', (select class_id from subclasses where name = 'Medic'), (select id from subclasses where name = 'Medic'), 4),
  ('Pain Killers', 'After modifying the available drugs in your kit, you’ve created pills that will eliminate potentially deadly afflictions. 3/day you may use your medical field kit as an action to cure any adjacent trainer or Pokémon of Burns, Poisoning, or Toxification. (A Pokémon who is healed this way cannot use a Move during the same round)', (select class_id from subclasses where name = 'Medic'), (select id from subclasses where name = 'Medic'), 6),
  ('Shock Therapy', 'After modifying the micro defibrillator in your kit, you’ve created a function of minor bursts of power to help friends in a tight spot. 3/day you may use your medical field kit as an action to cure any adjacent trainer or Pokémon of being Asleep or Freezing. (A Pokémon who is healed this way cannot use a Move during the same round)', (select class_id from subclasses where name = 'Medic'), (select id from subclasses where name = 'Medic'), 7),
  ('Restore Strength', 'By using a combination of energy recovering drugs and adrenaline, you’ve given your Pokémon a chance at pushing out more power in a tight spot. 3/day you may use your medical field kit as an action to restore an adjacent Pokémon’s use of 1/day or 3/day frequency moves as if they have rested for 8 hours. (A Pokémon who is healed this way cannot use a Move during the same round)', (select class_id from subclasses where name = 'Medic'), (select id from subclasses where name = 'Medic'), 8),
  ('Treat Major Wound', 'Your expertise of medicine has led to efficient use of your kit to repair the injured. 3/day you may use your medical field kit as an action to heal any adjacent trainer or Pokémon 30 hit points, then give them 15 temporary hit points which last for 10 mins. (A Pokémon who is healed this way cannot use a Move during the same round)', (select class_id from subclasses where name = 'Medic'), (select id from subclasses where name = 'Medic'), 10),
  ('Do No Harm', 'Your fervor in battle and willingness to risk your life while protecting others burns brightly as you save lives around you every day. On any turn where you haven’t attacked any targets and have not issued any attack commands to any of your Pokémon, your Treat Minor Wound, Treat Wound, Treat Major Wound and Treat Serious Wound features heal an additional 10 hit points, but grant 10 less temporary hit points. You may not issue attack commands to any Pokémon after benefitting from the Do No Harm feature', (select class_id from subclasses where name = 'Medic'), (select id from subclasses where name = 'Medic'), 11),
  ('Treat Serious Wound', 'Your mastery of medicine has led to perfect use of your kit to completely heal the injured. 3/day you may use your medical field as an action kit to heal any adjacent trainer or Pokémon 40 hit points, then give them 20 temporary hit points which last for 10 mins. (A Pokémon who is healed this way cannot use a Move during the same round)', (select class_id from subclasses where name = 'Medic'), (select id from subclasses where name = 'Medic'), 12),
  ('Won''t Die on Me', 'The lives of others are not expendable and your watch guarantees their survival. Once per day, if an adjacent ally fails their final death saving throw, they instead succeed the death saving throw and are set to 1 hit point, then regain consciousness', (select class_id from subclasses where name = 'Medic'), (select id from subclasses where name = 'Medic'), 13),

  ('Natural Tutoring', 'For a tutor, reteaching Pokémon how to do something they used to do before is a trivial exercise. Once per day, after spending one hour working with a Pokémon, you may teach a move to that Pokémon that they’ve known but have since removed from their move list as long as the Pokémon is proficient in its use', (select class_id from subclasses where name = 'Move tutor'), (select id from subclasses where name = 'Move tutor'), 1),
  ('Observation Training', 'Tutors figure out how to bring out the best from a Pokémon by studying attacks and by teaching your Pokémon everything there is to know about their own attacks, you’ve increased their odds of surviving in battle. Whenever one of your Pokémon is targeted by an attack they know, or used to know, their Defense, Special Defense, and Speed stat is raised +1 during the attacker’s accuracy check', (select class_id from subclasses where name = 'Move tutor'), (select id from subclasses where name = 'Move tutor'), 1),
  ('Passive Tutoring', 'By studying some basic field tactics you’ve learned how to teach Pokémon how to improve their odds on the field of battle. Once per day, after spending two hours working with a Pokémon, you may teach one of the following passives to that Pokémon: Defense Curl (+1 Defense), Howl (+1 Attack), Nasty Plot (+1 Special Attack), Run Away (+1 Speed), Confide (+1 Special Defense)', (select class_id from subclasses where name = 'Move tutor'), (select id from subclasses where name = 'Move tutor'), 2),
  ('Rudimentary Tutoring', 'There are some pretty basic things you’ve learned how to teach during your studies, and sometimes the most basic tricks should be taught. Once per day, after spending one hour working with a Pokémon, you may teach one of the following moves to that Pokémon, as long as it still fits the Pokémon’s proficiencies: Air Dart, Brutal Hit, Clearing Smog, Confusioning, Emberish, Fairy Wind, Icy Breeze, Karate Slap, Leafage, Metal Cut, Mud Throw, Rock Throw, Spook, Struggling Bug, Tackle, Thunder Spark, Twisting Gust, or Water Gun', (select class_id from subclasses where name = 'Move tutor'), (select id from subclasses where name = 'Move tutor'), 3),
  ('Machine Mentor', 'By studying the effects of Technical Machines and Technical Records, you’ve learned to replicate their techniques in training. Once per day, after spending six hours working with a Pokémon, you may teach that Pokémon any move you’ve previously taught with a Technical Machine or Technical Record. Moves taught with the Machine Mentor feature must still fit the Pokémon’s proficiencies', (select class_id from subclasses where name = 'Move tutor'), (select id from subclasses where name = 'Move tutor'), 4),
  ('Vocation Tutoring', 'After spending enough time in the study of Pokémon tutoring people will expect certain moves to be taught by you and you’re not one to disappoint. Once per day, after spending six hours working with a Pokémon, you may teach one of the following moves to that Pokémon, as long as it still fits the Pokémon’s proficiencies: Aerial Ace, Cross Poison, Dark Pulse, Dragon Tail, Energy Ball, Flamethrower, Ice Beam, Iron Head, Jump Kick, Moonblast, Mud Bomb, Power Gem, Psychic, Scald, Shadow Ball, Signal Beam, Swift, or Thunderbolt', (select class_id from subclasses where name = 'Move tutor'), (select id from subclasses where name = 'Move tutor'), 6),
  ('Field Tutoring', 'Battle tactics are just as important as battle prowess and a good move tutor knows how to bring out the best of field advantages in Pokémon. Once per day, after spending six hours working with a Pokémon, you may teach one of the following moves to that Pokémon, as long as it still fits the Pokémon’s proficiencies: Electric Terrain, Flower Shield, Grassy Terrain, Gravity, Hail, Haze, Ion Deluge, Magic Room, Mist, Misty Terrain, Psychic Terrain, Rain Dance, Sandstorm, Snowscape, Sunny Day, Tidepools, Trick Room, or Wonder Room', (select class_id from subclasses where name = 'Move tutor'), (select id from subclasses where name = 'Move tutor'), 7),
  ('Destructive Tutoring', 'Tweaking the main tricks of the trade let you teach Pokémon how to unleash grand displays of power. Once per day, after spending six hours working with a Pokémon, you may teach one of the following moves to that Pokémon, as long as it still fits the Pokémon’s type proficiencies: Blizzard, Close Combat, Draco Meteor, Earthquake, Fire Blast, Giga Impact, Gunk Shot, Hurricane, Hydro Pump, Hyper Beam, Megahorn, Meteor Rain, Moonwrecker, Poltergeist, Psionic Fury, Solar Beam, Stone Edge, Thunder, or Void Fury', (select class_id from subclasses where name = 'Move tutor'), (select id from subclasses where name = 'Move tutor'), 8),
  ('Class Time', 'Putting in the time to tutor Pokémon can be consuming for them, but you can split your attention without problems. While tutoring Pokémon, you can work with two Pokémon at a time and tutor both of them while using different Move Tutor features, or teach the same thing to both Pokémon with the same Move Tutor feature', (select class_id from subclasses where name = 'Move tutor'), (select id from subclasses where name = 'Move tutor'), 10),
  ('Photographic Tutoring', 'Memory serves well when training and mastering the ability to tutor moves and you’ve developed a near perfect mind when viewing how Pokémon produce attacks. Once per day, after spending six hours with a Pokémon, you may teach the Pokémon any non-legendary move you’ve seen used before. Moves taught with the Photographic Tutoring feature must still fit the Pokémon’s learnable moves description', (select class_id from subclasses where name = 'Move tutor'), (select id from subclasses where name = 'Move tutor'), 11),
  ('Passive Mastery', 'By spending time with Pokémon you’re able to bring out the best of their natural abilities that they have concealed within. Once per day, after spending six hours working with a Pokémon, you may teach the Pokémon any non-legendary, non-mega passive. You must use some reasoning here, for example if a Pokémon cannot produce water or ice, it cannot learn Refrigerate. You also cannot tutor unique passives, for example you can’t give Wonder Guard to any Pokémon, the passive explicitly mentions Shedinja in its effect description. You may not tutor the same Pokémon twice with Passive Mastery unless you’re replacing a passive previously taught with the Passive Mastery feature or if the passive taught with the Passive Mastery feature has previously been removed from that Pokémon’s passive list', (select class_id from subclasses where name = 'Move tutor'), (select id from subclasses where name = 'Move tutor'), 12),
  ('Tutor Mastery', 'You spent enough time practicing move theory. Now, you can apply it however you’d like. Once per day, after spending six hours working with one of your Pokémon, you may teach it any non-legendary move. You may tutor moves that do not fit your Pokémon’s learnable moves description. You may not tutor the same Pokémon twice with Tutor Mastery unless you’re replacing a move previously taught with the Tutor Mastery feature or if the move taught with the Tutor Mastery feature has previously been removed from that Pokémon’s move list. Natural Tutoring does not enable you to reteach moves learned through Tutor Mastery', (select class_id from subclasses where name = 'Move tutor'), (select id from subclasses where name = 'Move tutor'), 13);
